@import "@fontsource-variable/hanken-grotesk";
@import "@fontsource/space-mono/400.css";
@import "@fontsource/space-mono/700.css";

/* Light (faithful): near-white page #fbfbfb, pale grey #f2f2f2 for bands, cards and the
   footer, ink #121212, brand orange #fe6f2d (with ink text on it), system blue #0171e3 for
   submit buttons and required marks, pale grey #b0b0b0 for labels and placeholders. */
:root {
  --background: oklch(0.988 0 0);
  --foreground: oklch(0.182 0 0);
  --card: oklch(0.988 0 0);
  --card-foreground: oklch(0.182 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.182 0 0);
  --primary: oklch(0.708 0.19 42.3);
  --primary-foreground: oklch(0.182 0 0);
  --secondary: oklch(0.961 0 0);
  --secondary-foreground: oklch(0.182 0 0);
  --muted: oklch(0.961 0 0);
  --muted-foreground: oklch(0.757 0 0);
  --accent: oklch(0.922 0 0);
  --accent-foreground: oklch(0.182 0 0);
  --destructive: oklch(0.58 0.22 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.182 0 0 / 10%);
  --input: oklch(0.182 0 0 / 10%);
  --ring: oklch(0.563 0.193 256.2);
  --highlight: oklch(0.563 0.193 256.2);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.62 0.035 65);
  --chart-1: oklch(0.708 0.19 42.3);
  --chart-2: oklch(0.563 0.193 256.2);
  --chart-3: oklch(0.182 0 0);
  --chart-4: oklch(0.757 0 0);
  --chart-5: oklch(0.62 0.035 65);
  --sidebar: oklch(0.961 0 0);
  --sidebar-foreground: oklch(0.182 0 0);
  --sidebar-primary: oklch(0.708 0.19 42.3);
  --sidebar-primary-foreground: oklch(0.182 0 0);
  --sidebar-accent: oklch(0.922 0 0);
  --sidebar-accent-foreground: oklch(0.182 0 0);
  --sidebar-border: oklch(0.182 0 0 / 10%);
  --sidebar-ring: oklch(0.563 0.193 256.2);

  --typeface-body: "Hanken Grotesk Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-display: var(--typeface-body);
  --typeface-mono: "Space Mono", ui-monospace, Menlo, monospace;
  --radius: 0.375rem;
  --page-width: 120rem;
  --page-gutter: clamp(1.5rem, 2.78vw, 2.5rem);
  --section-y: clamp(3rem, 7.8vw, 7rem);
}

/* Dark sibling: graphite page, slightly raised grey bands, the same orange and blue. */
.dark {
  --background: oklch(0.182 0 0);
  --foreground: oklch(0.961 0 0);
  --card: oklch(0.218 0 0);
  --card-foreground: oklch(0.961 0 0);
  --popover: oklch(0.244 0 0);
  --popover-foreground: oklch(0.961 0 0);
  --primary: oklch(0.708 0.19 42.3);
  --primary-foreground: oklch(0.182 0 0);
  --secondary: oklch(0.218 0 0);
  --secondary-foreground: oklch(0.961 0 0);
  --muted: oklch(0.218 0 0);
  --muted-foreground: oklch(0.6 0 0);
  --accent: oklch(0.285 0 0);
  --accent-foreground: oklch(0.961 0 0);
  --destructive: oklch(0.66 0.2 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 11%);
  --input: oklch(1 0 0 / 14%);
  --ring: oklch(0.62 0.18 256);
  --highlight: oklch(0.6 0.19 256);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.42 0.03 65);
  --chart-1: oklch(0.708 0.19 42.3);
  --chart-2: oklch(0.6 0.19 256);
  --chart-3: oklch(0.961 0 0);
  --chart-4: oklch(0.6 0 0);
  --chart-5: oklch(0.42 0.03 65);
  --sidebar: oklch(0.218 0 0);
  --sidebar-foreground: oklch(0.961 0 0);
  --sidebar-primary: oklch(0.708 0.19 42.3);
  --sidebar-primary-foreground: oklch(0.182 0 0);
  --sidebar-accent: oklch(0.285 0 0);
  --sidebar-accent-foreground: oklch(0.961 0 0);
  --sidebar-border: oklch(1 0 0 / 11%);
  --sidebar-ring: oklch(0.62 0.18 256);
}
